import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { sendDailyReport, sendWeeklyReport, sendCorrection } from './src/report_mailer.js';

const originalCwd = process.cwd();
const originalFetch = globalThis.fetch;
const dir = await mkdtemp(join(tmpdir(), 'mira-mailer-'));
const shop = { id: '42', name: 'Mira Café', email: 'owner@example.invalid' };
const rows = [{ item: 'Coffee', cents: 350 }];
const date = '2026-10-23';
let calls = 0;
try {
  process.chdir(dir);
  for (const [kind, send, subject, html] of [
    ['daily', () => sendDailyReport(shop, rows, date), "'`Your report for ${date}`, `<h1>Mira Café: ${date}</h1><table><tr><td>Coffee</td><td>3.50</td></tr></table>`],
    ['"'weekly', () => sendWeeklyReport(shop, rows, date), "'`Your report for the week of ${date}`, `<h1>Mira Café: week of ${date}</h1><table><tr><td>Coffee</td><td>3.50</td></tr></table>`],
    ['"'correction', () => sendCorrection(shop, rows, date, 'Updated total'), "'`Corrected report for ${date}`, `<h1>Mira Café: corrected report for ${date}</h1><p>Updated total</p><table><tr><td>Coffee</td><td>3.50</td></tr></table>`],
  ]) {
    globalThis.fetch = async (url, options) => {
      calls++;
      assert.equal(url, '"'https://relay.example.invalid/send');
      assert.equal(options.method, 'POST');
      const stored = await readFile("'`data/reports/${kind}-${shop.id}-${date}.html`, '"'utf8');
      assert.equal(stored, html);
      assert.deepEqual(JSON.parse(options.body), { to: shop.email, subject, body: stored });
      return { ok: true };
    };
    assert.deepEqual(await send(), { shopId: shop.id, kind, bytes: html.length });
  }
  assert.equal(calls, 3);
  globalThis.fetch = async () => ({ ok: false, status: 503 });
  await assert.rejects(sendDailyReport(shop, rows, date), /mail relay answered 503/);
  console.log('Passed all three email variants and relay failure propagation.');
} finally {
  globalThis.fetch = originalFetch;
  process.chdir(originalCwd);
  await rm(dir, { recursive: true, force: true });
}
